export interface ThreadContextReadResponse { threadId: string; contextVersion: string; projectionStage: 'durable_pre_hooks';
  estimates: { estimated: true; estimator: 'local_cjk_character_estimate_v1'; parts: { instructions: number | null; tools: number | null; history: number | null; summary: number | null; pendingInput: number | null; }; total: number | null; };
  limits: { contextWindow: number | null; maxOutputTokens: number | null; runtimeContextWindow: number | null; outputReserve: number | null; outputReserveSource: string | null; compactionThreshold: number | null; };
  lastCompaction: { seq: number; turnId: string; createdAt: number; replacedMessageCount: number; summary: string; } | null;
  counts: { rawRecordCount: number; rawHistoryMessages: number; modelVisibleMessages: number; modelVisibleHistoryMessages: number; pendingInputs: number; }; }
export interface ThreadListParams {
  includeArchived?: boolean; archived?: boolean; offset?: number; limit?: number;
}
export type InputItem = JsonObject;
export interface TurnStartParams { threadId: string; inputId: string; expectedTurnId: string | null; input: InputItem[]; metadata?: JsonObject; }
export interface TurnResumeParams { threadId: string; turnId: string; }
export interface TurnSteerParams { threadId: string; inputId: string; expectedTurnId: string; input: InputItem[]; }
export interface TurnFollowUpParams { threadId: string; inputId: string; expectedTurnId: string; input: InputItem[]; }
export interface TurnInterruptParams { threadId: string; actionId: string; expectedTurnId: string; }
export interface ApprovalRequestParams {
  requestId: string; threadId: string; turnId: string; toolCallId: string;
  toolName: string; preview: string; arguments: JsonObject;
}
export interface ApprovalResolveParams {
  requestId: string; threadId: string; turnId: string; decision: ApprovalDecision;
  reason?: string; metadata?: JsonObject;
}

export interface AppItem {
  itemId: string; threadId: string; turnId: string; type: string; status: AppItemStatus;
  payload: JsonObject; createdAt: number; updatedAt: number;
}
export interface AppThread {
  threadId: string; agentKey: string; cwd: string | null; createdAt: number; updatedAt: number;
  archivedAt: number | null; status: ThreadStatus; metadata: JsonObject;
}
export interface AppTurn {
  turnId: string; threadId: string; runId: string | null; status: TurnStatus;
  startedAt: number; completedAt: number | null; input: InputItem[]; result: JsonObject;
}
export interface ToolCallDeltaParams extends AppItem { delta: JsonValue; }
export interface WarningParams { message: string; code?: string; }
export interface InitializeResponse { userAgent: string; protocolVersion: "v4"; capabilities: ServerCapabilities; }
export interface ModelSummary {
  id: string; provider?: string; displayName?: string; contextLength: number | null;
  supportsTools: boolean | null; maxOutputTokens: number | null; supportsVision: boolean | null;
  inputModalities: string[] | null; supportsReasoning: boolean | null; supportedReasoningEfforts: string[] | null;
  defaultReasoningEffort: string | null; supportsPromptCache: boolean | null; supportsContinuation: boolean | null; metadata?: JsonObject;
}
export interface ModelListResponse { models: ModelSummary[]; }
export interface ThreadStartResponse { threadId: string; agentKey: string; cwd: string | null; status: ThreadStatus; accepted: true; replayed: boolean; }
export interface ThreadReadResponse { thread: AppThread; turns: AppTurn[]; items: AppItem[]; }
export interface ThreadResumeResponse { thread: AppThread; turns: AppTurn[]; items: AppItem[]; }
export interface ThreadListResponse { threads: AppThread[]; }
export interface ThreadArchiveResponse { threadId: string; archived: boolean; }
